          /*not(local!vistaConformarMovimientos),*/
          /*not(local!vistaRechazarMovimientos),*/
          /*not(local!vistaHistorialComentarios),*/
          /*not(local!vistaActualizar),*/
          /*not(local!vistaCerrar),*/
          /*not(local!popUp_Recalcular)*/
          /*),*/

